use crate::{Game,Value,original_combat,original_route,Crew};
fn field(crew:&str)->Game{let mut g=Game::new(0,1,0x447d50);g.map.original=true;g.map.width=128;g.map.height=128;g.map.world=0;g.map.tiles=vec![0;16384];g.map.terrain_codes=vec![0;16384];g.map.native_terrain_plane=vec![0;16384];g.map.native_tile_plane=vec![0;16384];g.map.original_tiles=vec![0;16384];g.map.bridge_base=vec![-1;16384];g.map.territory=vec![0;16384];g.map.native_road_graph=Some(original_route::RoadGraph{regions:vec![original_route::RoadRegion{bounds:[0;4],waypoint:0,next:vec![255;96]};96]});g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.ai_teams.clear();g.native_group_rosters.clear();g.native_world=None;g.native_ambient=None;g.winner=None;g.import_native_world(&Value::Null);g.spawn("apc",0,640.,640.,1,Some(Crew{kind:crew.into(),hp:100.}));g.spawn("medium",1,3500.,3500.,2,None);g.maintain_native_group_rosters();let slot=g.units[0].native_slot.unwrap();g.native_group_rosters.observe_unit_context(slot);let other=g.units[1].native_slot.unwrap();g.native_group_rosters.members[other].as_mut().unwrap().flags69|=64;g.record_native_selection_saved_class(slot,if crew=="tough"{3}else if crew=="pyro"{15}else{0});g.native_routes.get_mut().managed[slot]=true;g.native_route_mode=true;g.units[0].native_phase35=56;g.units[0].native_counter68=8;g.units[0].native_reload7b=127;g.units[0].native_flags64=16;g.units[0].native_target42=0x1234;g.units[0].native_target46=0x5501;let w=g.units[0].native_hardware_slot.unwrap();g.native_hardware_pool[w].attributes.bytes[4]=0xf2;let mut o=g.native_hardware_pool[w].order;o.field17=0;g.native_hardware_pool[w].set_order(o);g.prepare_native_ambient_queries();g}
#[test]fn actual_phase56_main_enters_the_common_body_once_before_automatic_tail(){let mut g=field("tough");let w=g.units[0].native_hardware_slot.unwrap();g.step(0.059);assert_eq!(g.native_route_boundary,None);assert_eq!(g.units[0].native_phase35,56);assert_eq!(g.units[0].native_counter68,7,"447d50 must run exactly one45c5c0 DEC68");assert_eq!(g.native_hardware_pool[w].attributes.bytes[4],0xf1,"one W4 body pass");assert_eq!((g.units[0].native_target42,g.units[0].native_target46),(0x1234,0x5501));}

#[test]fn actual_phase56_counts_one_common_and_one_legacy_tail_without_a_footer_point_replay(){let mut g=field("tough");let slot=g.units[0].native_slot.unwrap();g.native_hardware_common.apc_scope=5;crate::original_apc56::take_trace();g.step(0.059);assert_eq!(crate::original_apc56::take_trace(),vec![(0,"Common"),(0,"LegacyAutomatic")]);assert_eq!(g.native_hardware_common.apc_scope,0);assert_eq!(g.units[0].native_common_callback,Some(g.motion_tick));assert_eq!(g.native_common_legacy.iter().filter(|x|**x==(slot as u8,crate::original_hardware_common::LegacyCall::ApcAuto447c20)).count(),1);assert_eq!(g.units[0].native_counter68,7);}
fn point(g:&mut Game){let slot=g.units[0].native_slot.unwrap();let m=g.native_group_rosters.members[slot].as_mut().unwrap();m.flags69|=32;m.promotion.target_x=460;m.promotion.target_y=320;g.units[0].native_reload7b=0;g.ensure_native_hardware(0);}
#[test]fn owned_manual_point_runs_once_and_preserves_its_prior_rng_when_the_pool_is_full(){for full in[false,true]{for mp in[false,true]{let mut g=field("tough");g.multiplayer=mp;g.original_rng.multiplayer=mp;point(&mut g);if full{let u=g.units[0].clone();for _ in 0..50{assert!(g.emit_native_projectile(&u,(100,100),(1200,1200),crate::original_projectiles::Kind::Rocket,15,1600,original_combat::Attack::from_unit(&u,usize::MAX,18.,0.)));}}let count=g.projectiles.len();let mut rng=g.original_rng.clone();rng.next_u32();rng.next_u32();crate::original_apc56::take_trace();g.step(0.059);assert_eq!(g.native_route_boundary,None);assert_eq!(g.projectiles.len(),count+usize::from(!full));assert_eq!(g.original_rng.words,rng.words,"the existing manual backend consumes two pre-allocation draws");assert_eq!(g.units[0].native_reload7b,20);assert_eq!(g.units[0].native_hardware.as_ref().unwrap().passenger_phase[0],1);assert_eq!(crate::original_apc56::take_trace(),vec![(0,"Common"),(0,"LegacyAutomatic")]);assert_eq!(g.native_common_legacy.iter().filter(|(_,r)|*r==crate::original_hardware_common::LegacyCall::ApcManual447da0).count(),1);assert_eq!(g.native_common_legacy.iter().filter(|(_,r)|*r==crate::original_hardware_common::LegacyCall::ApcAuto447c20).count(),1);}}}
#[test]fn owned_pyro_manual_gate_skips_release_without_skipping_the_automatic_admission(){let mut g=field("pyro");point(&mut g);g.units[0].native_hardware.as_mut().unwrap().passenger_phase[0]=3;let rng=g.original_rng.words;crate::original_apc56::take_trace();g.step(0.059);assert_eq!(g.native_route_boundary,None);assert!(g.projectiles.is_empty());assert_eq!(g.units[0].native_hardware.as_ref().unwrap().passenger_phase[0],4);assert_eq!(g.units[0].native_reload7b,20);assert_eq!(g.original_rng.words,rng);assert_eq!(crate::original_apc56::take_trace(),vec![(0,"Common"),(0,"LegacyAutomatic")]);}
#[test]fn wrapper_scope_is_one_process_state_and_has_no_unsourced_mission_reset(){let mut g=field("tough");g.native_hardware_common.apc_scope=5;crate::GAME.with(|c|*c.borrow_mut()=Some(g));crate::request(crate::json!({"op":"init","mission":1,"seed":13}));crate::GAME.with(|c|assert_eq!(c.borrow().as_ref().unwrap().native_hardware_common.apc_scope,5));}

#[test]fn automatic_release_uses_the_live_position_after_common_movement(){for mp in[false,true]{let mut g=field("tough");g.multiplayer=mp;g.original_rng.multiplayer=mp;g.units[1].x=800.;g.units[1].y=640.;g.initialize_native_walk_fields(1);g.refresh_native_pattern_step(1,0);g.units[0].native_reload7b=0;g.start_native_walking_direct(0,[500,320]);g.units[0].native_phase35=56;let before=g.units[0].x;let mut emitted=false;for _ in 0..12{crate::original_apc56::take_trace();g.step(0.059);assert_eq!(g.native_route_boundary,None);let shots=g.events.iter().filter(|v|v["weapon"]=="passenger"&&v["carrier"]==g.units[0].id).collect::<Vec<_>>();if !shots.is_empty(){assert!(g.units[0].x>before,"actual Common must move before sidefire");let u=&g.units[0];let direction=usize::from(original_combat::facing(u.angle));let possible=(0..12).map(|seat|{let table=match seat%4{0=>crate::native_weapon_data::APC_FRONT,1=>crate::native_weapon_data::APC_RIGHT,2=>crate::native_weapon_data::APC_BACK,_=>crate::native_weapon_data::APC_LEFT};let o=table[direction*3+seat/4];[(u.x/2.).floor()as i32+o[0]-6,(u.y/2.).floor()as i32+o[1]-6]}).collect::<Vec<_>>();for shot in shots{let p=[shot["x"].as_i64().unwrap()as i32/2,shot["y"].as_i64().unwrap()as i32/2];assert!(possible.contains(&p),"origin {p:?} must use live postCommon APC position");}assert_eq!(crate::original_apc56::take_trace(),vec![(0,"Common"),(0,"LegacyAutomatic")]);emitted=true;break;}}assert!(emitted,"the existing automatic passenger backend must remain reachable");}}

#[test]fn owned_unit_target_uses_the_common_manual_owner_without_the_old_ui_prefix(){for mp in[false,true]{let mut g=field("tough");g.multiplayer=mp;g.original_rng.multiplayer=mp;g.units[1].x=760.;g.units[1].y=640.;g.initialize_native_walk_fields(1);g.refresh_native_pattern_step(1,0);g.units[0].order="attack".into();g.units[0].target=Some(g.units[1].id);g.units[0].angle=crate::native_math::angle(2);g.units[0].native_timer3c=0;g.units[0].native_counter84=-1;g.units[0].native_reload7b=0;let slot=g.units[0].native_slot.unwrap();let target=g.units[1].native_slot.unwrap();let m=g.native_group_rosters.members[slot].as_mut().unwrap();m.flags31|=16;m.flags69|=128;let w=g.units[0].native_hardware_slot.unwrap();let mut order=g.native_hardware_pool[w].order;order.target=[-4321,target as i16];g.native_hardware_pool[w].set_order(order);g.native_hardware_pool[w].attributes.bytes[21]=2;crate::original_apc56::take_trace();g.step(0.059);assert_eq!(g.native_route_boundary,None);assert_eq!(g.projectiles.len(),1);assert_eq!(g.native_common_legacy.iter().filter(|(_,r)|*r==crate::original_hardware_common::LegacyCall::ApcManual447da0).count(),1);assert_eq!(crate::original_apc56::take_trace(),vec![(0,"Common"),(0,"LegacyAutomatic")]);assert_eq!(g.native_hardware_pool[w].order.target,[-4321,target as i16]);assert_eq!(g.units[0].native_reload7b,20);}}
#[test]fn frozen_main_stops_before_phase56_wrapper_and_does_not_reset_the_scope(){let mut g=field("tough");let slot=g.units[0].native_slot.unwrap();g.native_group_rosters.members[slot].as_mut().unwrap().flags69|=64;g.native_hardware_common.apc_scope=5;crate::original_apc56::take_trace();g.step(0.059);assert_eq!(g.native_route_boundary,None);assert!(crate::original_apc56::take_trace().is_empty());assert_eq!(g.native_hardware_common.apc_scope,5);assert_eq!(g.units[0].native_counter68,8);assert_eq!(g.units[0].native_phase35,56);}
#[test]fn actual_owned_phase56_rows_keep_their_public_phase_and_skip_private_scope_fields(){let mut states=vec![];for mp in[false,true]{let mut g=field("tough");g.multiplayer=mp;g.original_rng.multiplayer=mp;g.step(0.059);assert_eq!(g.native_route_boundary,None);let s=crate::game_snapshot(&g,&crate::json!({}));assert_eq!(s["units"][0]["nativePhase35"],56);assert!(s.get("nativeHardwareCommon").is_none());assert!(s["units"][0].get("nativeCommonCallback").is_none());states.push(s);}if let Some(p)=std::env::var_os("NATIVE_APC56_RPC_OUTPUT"){std::fs::write(p,serde_json::to_vec(&states).unwrap()).unwrap();}}
